def semver_sort(versions):
    def parse(v):
        main = v
        build = ''
        if '+' in main:
            main, build = main.split('+', 1)
        prerelease = None
        if '-' in main:
            core, prerelease = main.split('-', 1)
        else:
            core = main
        parts = core.split('.')
        major, minor, patch = (int(parts[0]), int(parts[1]), int(parts[2]))
        return major, minor, patch, prerelease

    def prerelease_key(prerelease):
        if prerelease is None:
            return (1,)  # no prerelease -> sorts after
        ids = prerelease.split('.')
        key_parts = []
        for ident in ids:
            if ident.isdigit():
                key_parts.append((0, int(ident), ''))
            else:
                key_parts.append((1, 0, ident))
        return (0, len(key_parts), tuple(key_parts))

    def sort_key(v):
        major, minor, patch, prerelease = parse(v)
        return (major, minor, patch, prerelease_key(prerelease))

    return sorted(versions, key=sort_key)

